<template>
  <div>
    <el-form :inline="true" :model="queryForm" size="small">
      <el-form-item>
        <el-select
          v-model="queryForm.source_id"
          placeholder="请选择设备"
          clearable
        >
          <el-option
            v-for="item in deviceList"
            :key="item.id"
            :label="item.source_name"
            :value="item.id"
          ></el-option>
        </el-select>
      </el-form-item>
      <el-form-item>
        <el-date-picker
          v-model="dateList"
          type="datetimerange"
          range-separator="至"
          start-placeholder="开始日期"
          end-placeholder="结束日期"
          value-format="yyyy-MM-dd HH:mm:ss"
        >
        </el-date-picker>
      </el-form-item>
      <el-form-item>
        <el-button type="primary" @click="query">查询</el-button>
        <el-button @click="reset">重置</el-button>
      </el-form-item>
    </el-form>

    <el-table :data="recordsList">
      <el-table-column label="序号" type="index" align="center" />
      <el-table-column label="设备名称" align="center" prop="source_name" />
      <el-table-column label="通道名称" align="center" prop="describe" />
      <el-table-column
        label="视频名称"
        align="center"
        prop="file_name"
        width="220"
      />
      <el-table-column
        label="视频录制类型"
        align="center"
        prop="video_record_type"
      >
        <template slot-scope="scope">
          {{ scope.row.video_record_type == 1 ? "全天录制" : "报警录制" }}
        </template>
      </el-table-column>
      <el-table-column label="视频大小" align="center" prop="file_size">
        <template slot-scope="scope">
          {{ bytesToMegabytes(scope.row.file_size) }}M
        </template>
      </el-table-column>
      <el-table-column label="录制时长" align="center" prop="time_len">
        <template slot-scope="scope">
          {{ scope.row.time_len | toFixed }}s
        </template>
      </el-table-column>
      <el-table-column label="状态" align="center" prop="analyse_status">
        <template slot-scope="scope">
          {{ status[scope.row.analyse_status] }}
        </template>
      </el-table-column>
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button
            type="text"
            icon="el-icon-video-camera"
            @click="play(scope.row)"
          ></el-button>
        </template>
      </el-table-column>
    </el-table>

    <pagination
      class="float-right mb-10"
      v-show="total > 0"
      :total="total"
      :page.sync="queryForm.page"
      :limit.sync="queryForm.size"
      @pagination="getDataList"
      layout="total, prev, pager, next"
      small
    />
    <el-dialog
      :visible.sync="dialogVisible"
      title="视频录像"
      width="60%"
      top="20px"
      v-if="dialogVisible"
    >
      <!-- <videoPlayer
        controls
        ref="videoPlayer"
        v-if="dialogVisible"
        :src="videoSrc"
        style="height: 100%"
      ></videoPlayer> -->
      <video controls autoplay>
        <source :src="videoSrc" type="video/mp4" />
      </video>
    </el-dialog>
  </div>
</template>

<script>
// import videoPlayer from "@/components/videoPlayer.vue";

export default {
  // components: {
  //   videoPlayer,
  // },
  data() {
    return {
      queryForm: {
        page: 1,
        size: 10,
        source_id: "",
      },
      deviceList: [],
      dateList: [],
      recordsList: [],
      total: 0,
      videoSrc: "",
      dialogVisible: false,
      status: {
        0: "不显示",
        1: "未分析",
        2: "已分析",
      },
    };
  },
  filters: {
    toFixed(value) {
      return parseFloat(value).toFixed(2);
    },
  },
  created() {
    this.queryForm.source_id = Number(this.$route.query.source_id) || "";
    this.getDeviceList();
    this.getDataList();
  },
  methods: {
    bytesToMegabytes(bytes) {
      return (bytes / (1024 * 1024)).toFixed(2);
    },
    play(row) {
      this.videoSrc = row.file_path;
      this.dialogVisible = true;
    },
    getDeviceList() {
      this.$api
        .get(`/collect/getDataSourceList`, { params: { driver_protocol: 1 } })
        .then((res) => {
          if (res.data.data) {
            this.deviceList = res.data.data.filter(
              (item) => item.driver_protocol == 1
            );
            this.deviceList.unshift({
              id: "",
              source_name: "全部",
            });
          }
        });
    },
    //
    reset() {
      this.dateList = [];
      this.queryForm = {
        page: 1,
        size: 10,
        source_id: "",
      };
      this.getDataList();
    },
    query() {
      this.queryForm = {
        ...this.queryForm,
        page: 1,
        begin_time: this.dateList[0],
        end_time: this.dateList[1],
      };
      this.getDataList();
    },
    getDataList() {
      this.$api
        .get(`/collect/getVideoRecordList`, {
          params: this.queryForm,
        })
        .then((res) => {
          if (res.data.data) {
            this.recordsList = res.data.data;
            this.total = res.data.total;
          } else {
            this.total = 0;
            this.recordsList = [];
          }
        });
    },
  },
};
</script>

<style lang="scss" scoped>
video {
  width: 100%;
  height: 60vh;
}
::v-deep(.el-table__cell) {
  padding: 5px 0 !important;
}
</style>
